'use client';

import { useEffect, useMemo, useRef } from 'react';
import { crisp, makeScale, prepareCanvas, readTokens } from '../../canvas';
import { useElementSize } from '../../hooks';
import type { Candle } from '../../types';
import { cn, toArray } from '../../utils';

export type IndicatorKind = 'rsi' | 'macd' | 'volume';

export interface IndicatorPaneProps {
  candles: Candle[];
  kind?: IndicatorKind;
  /** RSI lookback, or the MACD signal period. */
  period?: number;
  /** MACD fast EMA. */
  fastPeriod?: number;
  /** MACD slow EMA. */
  slowPeriod?: number;
  height?: number;
  /** RSI only: the oversold / overbought rules drawn behind the line. */
  bands?: [number, number];
  className?: string;
  'aria-label'?: string;
}

const TOKENS = [
  '--up',
  '--down',
  '--chart-grid',
  '--chart-axis',
  '--muted-foreground',
  '--primary',
  '--foreground',
] as const;

const AXIS_WIDTH = 34;
const PAD = 6;

/** Wilder's RSI. `null` until the lookback is satisfied. */
export function rsi(closes: readonly number[], period = 14): (number | null)[] {
  const out: (number | null)[] = new Array(closes.length).fill(null);
  if (period < 1 || closes.length <= period) return out;

  let gain = 0;
  let loss = 0;
  for (let i = 1; i <= period; i++) {
    const change = closes[i] - closes[i - 1];
    if (change >= 0) gain += change;
    else loss -= change;
  }
  gain /= period;
  loss /= period;
  out[period] = loss === 0 ? 100 : 100 - 100 / (1 + gain / loss);

  // Wilder smoothing, not a rolling mean. The two disagree, and every desk and
  // charting package quotes the smoothed one.
  for (let i = period + 1; i < closes.length; i++) {
    const change = closes[i] - closes[i - 1];
    gain = (gain * (period - 1) + Math.max(0, change)) / period;
    loss = (loss * (period - 1) + Math.max(0, -change)) / period;
    out[i] = loss === 0 ? 100 : 100 - 100 / (1 + gain / loss);
  }
  return out;
}

/** Exponential moving average, seeded with a simple mean over the first window. */
export function ema(values: readonly number[], period: number): (number | null)[] {
  const out: (number | null)[] = new Array(values.length).fill(null);
  if (period < 1 || values.length < period) return out;
  const k = 2 / (period + 1);
  let acc = 0;
  for (let i = 0; i < period; i++) acc += values[i];
  let prev = acc / period;
  out[period - 1] = prev;
  for (let i = period; i < values.length; i++) {
    prev = values[i] * k + prev * (1 - k);
    out[i] = prev;
  }
  return out;
}

export interface MacdPoint {
  macd: number | null;
  signal: number | null;
  histogram: number | null;
}

/** MACD line, its signal EMA, and the histogram between them. */
export function macd(
  closes: readonly number[],
  fastPeriod = 12,
  slowPeriod = 26,
  signalPeriod = 9,
): MacdPoint[] {
  const fast = ema(closes, fastPeriod);
  const slow = ema(closes, slowPeriod);
  const line = closes.map((_, i) => {
    const f = fast[i];
    const s = slow[i];
    return f === null || s === null ? null : f - s;
  });

  // The signal EMA is seeded only from the bars where the MACD line exists.
  // Treating the leading nulls as zeroes drags the first signal values toward
  // the axis and prints a crossover that never happened.
  const defined = line.filter((v): v is number => v !== null);
  const signalTail = ema(defined, signalPeriod);
  const offset = line.length - defined.length;

  return line.map((value, i) => {
    const signal = i >= offset ? signalTail[i - offset] : null;
    return {
      macd: value,
      signal: signal ?? null,
      histogram: value !== null && signal != null ? value - signal : null,
    };
  });
}

/**
 * The sub-pane under a price chart: RSI, MACD or volume.
 *
 * Kept separate from `CandleChart` rather than bolted onto it, because an
 * oscillator has its own domain - RSI is 0-100, MACD straddles zero, volume is
 * unbounded - and folding them into the price scale is what makes a chart
 * unreadable. Share the x-axis by handing both components the same candles at
 * the same width.
 */
export function IndicatorPane({
  candles,
  kind = 'rsi',
  period = 14,
  fastPeriod = 12,
  slowPeriod = 26,
  height = 92,
  bands = [30, 70],
  className,
  'aria-label': ariaLabel,
}: IndicatorPaneProps) {
  const [wrapRef, size] = useElementSize<HTMLDivElement>();
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const bars = toArray(candles);
  const width = size.width;

  const series = useMemo(() => {
    const closes = bars.map((c) => c.close);
    if (kind === 'rsi') return { rsi: rsi(closes, period) };
    if (kind === 'macd') return { macd: macd(closes, fastPeriod, slowPeriod) };
    return { volume: bars.map((c) => c.volume) };
  }, [bars, kind, period, fastPeriod, slowPeriod]);

  useEffect(() => {
    const canvas = canvasRef.current;
    const wrap = wrapRef.current;
    if (!canvas || !wrap || width < 2 || height < 2 || bars.length === 0) return;

    const ctx = prepareCanvas(canvas, width, height);
    if (!ctx) return;
    const c = readTokens(wrap, TOKENS);

    const left = PAD;
    const right = width - AXIS_WIDTH;
    const top = PAD;
    const bottom = height - PAD;
    const plotWidth = Math.max(1, right - left);
    const slot = plotWidth / bars.length;
    const xOf = (i: number) => left + i * slot + slot / 2;

    ctx.font = '10px ui-monospace, monospace';
    ctx.textBaseline = 'middle';

    const axisLabel = (text: string, py: number) => {
      ctx.fillStyle = c['--muted-foreground'];
      ctx.textAlign = 'left';
      ctx.fillText(text, right + 4, py);
    };

    const polyline = (
      values: readonly (number | null)[],
      y: (v: number) => number,
      color: string,
      dash: number[] = [],
    ) => {
      ctx.strokeStyle = color;
      ctx.lineWidth = 1.4;
      ctx.setLineDash(dash);
      ctx.beginPath();
      let started = false;
      values.forEach((value, i) => {
        if (value === null) return;
        const px = xOf(i);
        const py = y(value);
        if (started) ctx.lineTo(px, py);
        else {
          ctx.moveTo(px, py);
          started = true;
        }
      });
      ctx.stroke();
      ctx.setLineDash([]);
    };

    if (kind === 'rsi') {
      const y = makeScale(0, 100, bottom, top);
      const [low, high] = bands;

      // Shade between the rules rather than only drawing them: "is it in the
      // middle" is the question this pane gets read for.
      ctx.fillStyle = c['--chart-grid'];
      ctx.globalAlpha = 0.35;
      ctx.fillRect(left, y(high), plotWidth, y(low) - y(high));
      ctx.globalAlpha = 1;

      ctx.strokeStyle = c['--chart-grid'];
      ctx.lineWidth = 1;
      for (const level of [low, 50, high]) {
        ctx.beginPath();
        ctx.moveTo(left, crisp(y(level)));
        ctx.lineTo(right, crisp(y(level)));
        ctx.stroke();
      }
      axisLabel(String(high), y(high));
      axisLabel(String(low), y(low));

      const values = series.rsi ?? [];
      let last: number | null = null;
      for (let i = values.length - 1; i >= 0; i--) {
        if (values[i] !== null) {
          last = values[i];
          break;
        }
      }
      const stroke =
        last === null
          ? c['--primary']
          : last >= high
            ? c['--down']
            : last <= low
              ? c['--up']
              : c['--primary'];
      polyline(values, y, stroke);
    }

    if (kind === 'macd') {
      const points = series.macd ?? [];
      let extreme = 0;
      for (const p of points) {
        for (const v of [p.macd, p.signal, p.histogram]) {
          if (v === null) continue;
          if (Math.abs(v) > extreme) extreme = Math.abs(v);
        }
      }
      // Symmetric around zero: a MACD pane whose zero line drifts off-centre
      // misreports the sign of the move at a glance.
      const span = extreme || 1;
      const y = makeScale(-span, span, bottom, top);

      ctx.strokeStyle = c['--chart-axis'];
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(left, crisp(y(0)));
      ctx.lineTo(right, crisp(y(0)));
      ctx.stroke();

      const barWidth = Math.max(1, slot * 0.6);
      const zero = y(0);
      ctx.globalAlpha = 0.55;
      points.forEach((p, i) => {
        if (p.histogram === null) return;
        ctx.fillStyle = p.histogram >= 0 ? c['--up'] : c['--down'];
        const py = y(p.histogram);
        ctx.fillRect(xOf(i) - barWidth / 2, Math.min(zero, py), barWidth, Math.abs(py - zero));
      });
      ctx.globalAlpha = 1;

      polyline(
        points.map((p) => p.macd),
        y,
        c['--primary'],
      );
      polyline(
        points.map((p) => p.signal),
        y,
        c['--muted-foreground'],
        [3, 2],
      );
      axisLabel('0', zero);
    }

    if (kind === 'volume') {
      const values = series.volume ?? [];
      const peak = Math.max(1, ...values);
      const y = makeScale(0, peak, bottom, top);
      const barWidth = Math.max(1, slot * 0.6);
      ctx.globalAlpha = 0.6;
      values.forEach((value, i) => {
        const bar = bars[i];
        ctx.fillStyle = bar.close >= bar.open ? c['--up'] : c['--down'];
        ctx.fillRect(xOf(i) - barWidth / 2, y(value), barWidth, bottom - y(value));
      });
      ctx.globalAlpha = 1;
    }
  }, [series, bars, kind, bands, width, height, wrapRef]);

  const title =
    kind === 'rsi' ? `RSI ${period}` : kind === 'macd' ? `MACD ${fastPeriod}/${slowPeriod}` : 'Volume';

  return (
    <div
      ref={wrapRef}
      data-slot="indicator-pane"
      className={cn('relative w-full', className)}
      style={{ height }}
      role="img"
      aria-label={ariaLabel ?? title}
    >
      <span className="text-muted-foreground pointer-events-none absolute top-1 left-2 z-10 text-[10px] font-medium tracking-wide uppercase">
        {title}
      </span>
      <canvas ref={canvasRef} className="block h-full w-full" style={{ width, height }} />
    </div>
  );
}

/** Canvas plumbing shared by the chart components. */

export interface ChartPadding {
  top: number;
  right: number;
  bottom: number;
  left: number;
}

/**
 * Sizes the backing store to the device pixel ratio and returns a context
 * already scaled to CSS pixels, so drawing code can use layout units and still
 * get crisp 1px gridlines on a HiDPI screen.
 */
export function prepareCanvas(
  canvas: HTMLCanvasElement,
  width: number,
  height: number,
): CanvasRenderingContext2D | null {
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const w = Math.max(1, Math.floor(width * dpr));
  const h = Math.max(1, Math.floor(height * dpr));
  if (canvas.width !== w) canvas.width = w;
  if (canvas.height !== h) canvas.height = h;

  const ctx = canvas.getContext('2d');
  if (!ctx) return null;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, width, height);
  return ctx;
}

/**
 * Resolves CSS custom properties against a live element. The charts paint on
 * canvas, which cannot inherit `var(--tu-up)`, so they read the tokens once
 * per draw and stay in sync with whatever theme the host applied.
 */
export function readTokens<K extends string>(
  el: Element,
  names: readonly K[],
): Record<K, string> {
  const style = getComputedStyle(el);
  const out = {} as Record<K, string>;
  for (const name of names) {
    out[name] = style.getPropertyValue(name).trim() || '#888';
  }
  return out;
}

/** Linear scale from a data domain to a pixel range. */
export function makeScale(
  domainMin: number,
  domainMax: number,
  rangeMin: number,
  rangeMax: number,
) {
  const span = domainMax - domainMin || 1;
  const pixels = rangeMax - rangeMin;
  const scale = (value: number) => rangeMin + ((value - domainMin) / span) * pixels;
  scale.invert = (pixel: number) => domainMin + ((pixel - rangeMin) / pixels) * span;
  return scale;
}

/**
 * "Nice" tick values at human-readable intervals (1, 2, 5 x 10^n) so the price
 * axis reads 42.50 / 43.00 / 43.50 instead of 42.37 / 42.91 / 43.45.
 */
export function niceTicks(min: number, max: number, target = 5): number[] {
  if (!Number.isFinite(min) || !Number.isFinite(max) || max <= min) return [min];
  const raw = (max - min) / target;
  const magnitude = Math.pow(10, Math.floor(Math.log10(raw)));
  const normalized = raw / magnitude;
  const step =
    (normalized >= 5 ? 10 : normalized >= 2 ? 5 : normalized >= 1 ? 2 : 1) * magnitude;

  const ticks: number[] = [];
  for (let t = Math.ceil(min / step) * step; t <= max + step * 1e-6; t += step) {
    ticks.push(Number(t.toFixed(10)));
  }
  return ticks;
}

/** Snaps a coordinate to a half-pixel so a 1px stroke lands on one pixel row. */
export function crisp(value: number): number {
  return Math.round(value) + 0.5;
}

/** Fills a rounded rect; `ctx.roundRect` is still patchy in older Safari. */
export function fillRoundRect(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  r: number,
) {
  const radius = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.lineTo(x + w - radius, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + radius);
  ctx.lineTo(x + w, y + h - radius);
  ctx.quadraticCurveTo(x + w, y + h, x + w - radius, y + h);
  ctx.lineTo(x + radius, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - radius);
  ctx.lineTo(x, y + radius);
  ctx.quadraticCurveTo(x, y, x + radius, y);
  ctx.fill();
}

/** Dashed horizontal rule used for the last-price and crosshair lines. */
export function dashedLine(
  ctx: CanvasRenderingContext2D,
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  dash: number[] = [3, 3],
) {
  ctx.save();
  ctx.setLineDash(dash);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
  ctx.restore();
}

'use client';

import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import type { Direction } from './types';

/**
 * Measures an element with ResizeObserver. Canvas charts need real pixel
 * dimensions, and in a resizable terminal layout those change constantly.
 */
export function useElementSize<T extends HTMLElement>() {
  const ref = useRef<T | null>(null);
  const [size, setSize] = useState({ width: 0, height: 0 });

  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;

    const read = () => {
      const rect = el.getBoundingClientRect();
      setSize((prev) =>
        // Sub-pixel churn would re-render on every scroll of a parent.
        Math.abs(prev.width - rect.width) < 0.5 &&
        Math.abs(prev.height - rect.height) < 0.5
          ? prev
          : { width: rect.width, height: rect.height },
      );
    };

    read();
    if (typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver(read);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  return [ref, size] as const;
}

/**
 * Reports which way a value last moved and clears back to `flat` after
 * `duration`, so a price cell can flash green/red on each tick.
 */
export function usePriceFlash(value: number, duration = 420): Direction {
  const previous = useRef(value);
  const [flash, setFlash] = useState<Direction>('flat');

  useEffect(() => {
    const prev = previous.current;
    previous.current = value;
    if (!Number.isFinite(value) || !Number.isFinite(prev) || value === prev) return;

    setFlash(value > prev ? 'up' : 'down');
    const t = setTimeout(() => setFlash('flat'), duration);
    return () => clearTimeout(t);
  }, [value, duration]);

  return flash;
}

/** The value from the previous render - handy for diffing feed snapshots. */
export function usePrevious<T>(value: T): T | undefined {
  const ref = useRef<T | undefined>(undefined);
  useEffect(() => {
    ref.current = value;
  }, [value]);
  return ref.current;
}

/**
 * requestAnimationFrame loop that stays mounted across re-renders. Used by the
 * mock feed and by chart crosshair redraws; `fps` throttles it.
 */
export function useAnimationFrame(callback: (dt: number) => void, fps = 60) {
  const cb = useRef(callback);
  cb.current = callback;

  useEffect(() => {
    if (fps <= 0) return;
    let raf = 0;
    let last = performance.now();
    const minDelta = 1000 / fps;

    const tick = (now: number) => {
      raf = requestAnimationFrame(tick);
      const dt = now - last;
      if (dt < minDelta) return;
      last = now;
      cb.current(dt);
    };

    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [fps]);
}

/** True when the user has asked the OS to reduce motion. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    if (typeof matchMedia !== 'function') return;
    const mq = matchMedia('(prefers-reduced-motion: reduce)');
    setReduced(mq.matches);
    const onChange = (e: MediaQueryListEvent) => setReduced(e.matches);
    mq.addEventListener('change', onChange);
    return () => mq.removeEventListener('change', onChange);
  }, []);
  return reduced;
}

/** Shared domain types. Deliberately plain so any feed can map onto them. */

export type Side = 'buy' | 'sell';
export type Direction = 'up' | 'down' | 'flat';

/** One OHLCV bar. `time` is epoch milliseconds at the bar's open. */
export interface Candle {
  time: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

/** A single price level in the book. */
export interface BookLevel {
  price: number;
  size: number;
}

export interface OrderBookSnapshot {
  /** Highest price first. */
  bids: BookLevel[];
  /** Lowest price first. */
  asks: BookLevel[];
}

export interface Trade {
  id: string;
  time: number;
  price: number;
  size: number;
  /** Aggressor side: `buy` means it lifted the offer. */
  side: Side;
}

export interface Quote {
  symbol: string;
  name?: string;
  last: number;
  /** Previous session close, used for the day change. */
  prevClose: number;
  bid?: number;
  ask?: number;
  dayHigh?: number;
  dayLow?: number;
  volume?: number;
  /** Optional intraday series for an inline sparkline. */
  history?: number[];
}

export interface Position {
  symbol: string;
  /** Signed: negative is short. */
  quantity: number;
  avgPrice: number;
  markPrice: number;
}

export type OrderType = 'market' | 'limit' | 'stop' | 'stop-limit';
export type OrderStatus = 'working' | 'filled' | 'partial' | 'cancelled' | 'rejected';

export interface OrderDraft {
  symbol: string;
  side: Side;
  type: OrderType;
  quantity: number;
  /** Required for limit / stop-limit. */
  limitPrice?: number;
  /** Required for stop / stop-limit. */
  stopPrice?: number;
  timeInForce: TimeInForce;
}

export type TimeInForce = 'day' | 'gtc' | 'ioc' | 'fok';

export interface Order extends OrderDraft {
  id: string;
  time: number;
  status: OrderStatus;
  filledQuantity: number;
  avgFillPrice?: number;
}

/** Price/size formatting rules for an instrument. */
export interface Instrument {
  symbol: string;
  name?: string;
  /** Decimal places for price. */
  pricePrecision: number;
  /** Minimum price increment. */
  tickSize: number;
  /** Decimal places for quantity. */
  sizePrecision?: number;
  /** Quote-currency symbol, e.g. "$". */
  currency?: string;
}

/**
 * One execution. Distinct from an `Order`: an order is an instruction, a fill
 * is what actually happened to it, and a single order can produce many fills
 * at different prices. Reconciliation, cost basis and fee accounting all work
 * off fills, never off orders.
 */
export interface Fill {
  id: string;
  /** The order this execution belongs to, for grouping a partial sequence. */
  orderId?: string;
  symbol: string;
  time: number;
  side: Side;
  quantity: number;
  price: number;
  /** Commission or exchange fee, in the quote currency. Negative is a rebate. */
  fee?: number;
  /** `maker` rested and was hit; `taker` crossed the spread. Drives the fee. */
  liquidity?: 'maker' | 'taker';
  venue?: string;
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

/**
 * Merge Tailwind classes with later ones winning - the same `cn` shadcn/ui
 * uses, so a consumer can override any class on any component by passing
 * `className`, with no specificity war.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/** Shared empty array, so a normalized-away prop keeps a stable identity and
 *  does not invalidate the `useMemo` that depends on it on every render. */
const EMPTY: readonly never[] = Object.freeze([]);

/**
 * Coerces a feed-supplied collection to something safe to iterate.
 *
 * A live feed is not a type system. Sockets drop fields, REST returns `null`
 * for "no rows yet", and a panel mounts before its first payload lands. None
 * of that should unmount the React tree — a component with nothing to show
 * renders its empty state instead. Returns a frozen shared array when the
 * input is unusable, so the identity stays stable across renders.
 */
export function toArray<T>(value: readonly T[] | null | undefined): readonly T[] {
  return Array.isArray(value) ? value : (EMPTY as readonly T[]);
}

/** `toArray` for both sides of a book, tolerating a missing snapshot entirely. */
export function toBook<T>(book: { bids?: readonly T[] | null; asks?: readonly T[] | null } | null | undefined) {
  return { bids: toArray(book?.bids), asks: toArray(book?.asks) };
}
